import { errorMessage } from '../utils/errorMessage';
import type { FailureReasonCode } from '../utils/failureReason';

const BLOCK_TIMEOUT_PATTERN = /block timeout reached/i;

const describeFailure = (command: string, cause: string, isTimeout: boolean) =>
  isTimeout
    ? `git ${command} produced no output before Rivet's git timeout while snapshotting the project. ` +
      `Large folders that git does not ignore (dependencies, build output, media) are the usual cause. ` +
      `Add them to .gitignore, then generate the directions again.`
    : `git ${command} failed while snapshotting the project: ${cause}`;

export class GitCommandError extends Error {
  readonly gitCommand: string;
  readonly reasonCode: FailureReasonCode;

  constructor({ command, error }: { command: string; error: unknown }) {
    const cause = errorMessage(error);
    const isTimeout = BLOCK_TIMEOUT_PATTERN.test(cause);
    super(describeFailure(command, cause, isTimeout));
    this.name = 'GitCommandError';
    this.gitCommand = command;
    this.reasonCode = isTimeout ? 'timeout' : 'unknown';
  }
}

export const runGitCommand = async <T>(
  command: string,
  run: () => Promise<T>,
): Promise<T> => {
  try {
    return await run();
  } catch (error) {
    throw new GitCommandError({ command, error });
  }
};
